# Robust filtering using actual column names present in the CSV
# (some versions use "Total Gross" / "Gross" naming variations)
gross_col = None
for c in ["Total Gross (millions)", "Total Gross", "Gross", "Total Gross (Millions)"]:
    if c in df.columns:
        gross_col = c
        break

if gross_col is None:
    raise KeyError(f"Could not find a gross column. Available columns: {list(df.columns)}")

clean_df = df[~df[gross_col].astype(str).isin(["$0.00M", "Gross Unkown"])].copy()

if "Censor" in clean_df.columns:
    clean_df = clean_df[clean_df["Censor"] != "(Banned)"]
